@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  canActivate(ctx: ExecutionContext): boolean {
    // Method-level @Roles overrides class-level @Roles
    const roles = this.reflector.getAllAndOverride<string[]>('roles', [
      ctx.getHandler(), // the route method about to run
      ctx.getClass(),   // its controller class
    ]);
    if (!roles) return true;
    const req = ctx.switchToHttp().getRequest(); // branch on ctx.getType() for ws/gql
    return roles.some((r) => req.user?.roles?.includes(r));
  }
}

